42	const validator = `
43	import json
44	import sys
45	from jsonschema import Draft7Validator
46	from referencing import Registry, Resource
47	
48	with open(sys.argv[1], encoding='utf-8') as schema_file:
49	    schema = json.load(schema_file)
50	fixture = json.load(sys.stdin)
51	registry = Registry().with_resource(schema['$id'], Resource.from_contents(schema))
52	errors = list(Draft7Validator(schema, registry=registry).iter_errors(fixture))
53	for error in errors:
54	    print(f'{error.json_path}: {error.message}')
55	sys.exit(1 if errors else 0)
56	`;
57	
58	function schemaErrors(fixture: unknown): string {
59	  const result = spawnSync(pythonPath, ['-c', validator, schemaPath], {
60	    encoding: 'utf8',
61	    input: JSON.stringify(fixture),
62	  });
63	
64	  if (result.error) throw result.error;
65	  return result.stdout.trim();
66	}
