75	    lesson_schema = json.load(lesson_file)
76	with open(sys.argv[2], encoding='utf-8') as activity_file:
77	    activity_schema = json.load(activity_file)
78	fixture = json.load(sys.stdin)
79	registry = Registry().with_resources([
80	    (activity_schema['$id'], Resource.from_contents(activity_schema)),
