26	
27	export interface ActivityPlayerProps {
28	  activity: ActivityPlayerActivity;
29	  onComplete?: (event: ActivityCompletionEvent) => void;
30	  /**
31	   * Reserved for controlled editor integrations. This player has no editor UI
32	   * and never transports events; an editor can emit this local operation shape.
33	   */
34	  onEdit?: (operation: ActivityEditOperation) => void;
35	  isUkrainian?: boolean;
36	}
