43	export function ClozePassage({ text, blanks, isUkrainian, onComplete }: ClozePassageProps) {
44	  // Pre-shuffle options for each blank on mount
45	  const shuffledBlanks = useMemo(() =>
46	    blanks.map(blank => ({
47	      ...blank,
48	      options: shuffle([...blank.options])
49	    })),
50	    [blanks]
51	  );
52	
53	  const [selections, setSelections] = useState<Map<number, string>>(new Map());
54	  const [submitted, setSubmitted] = useState(false);
55	
56	  const handleSelect = (index: number, value: string) => {
57	    if (submitted) return;
58	    const newSelections = new Map(selections);
59	    newSelections.set(index, value);
60	    setSelections(newSelections);
61	  };
62	
63	  const handleSubmit = () => {
64	    setSubmitted(true);
65	    onComplete?.();
66	  };
67	
68	  const handleReset = () => {
69	    setSelections(new Map());
70	    setSubmitted(false);
71	  };
72	
73	  // Check if all answers are correct
74	  const allCorrect = blanks.every(blank =>
75	    selections.get(blank.index)?.toLowerCase().trim() === blank.answer.toLowerCase().trim()
76	  );
77	
78	  // Parse text and replace [___:N] with select elements
79	  const renderText = () => {
80	    const parts: React.ReactNode[] = [];
81	    let lastIndex = 0;
82	    const regex = /\[___:(\d+)\]/g;
83	    let match;
84	
85	    while ((match = regex.exec(text)) !== null) {
86	      // Add text before this blank
87	      if (match.index > lastIndex) {
88	        parts.push(text.slice(lastIndex, match.index));
89	      }
90	
91	      const optionIndex = parseInt(match[1], 10);
92	      const blank = shuffledBlanks.find(b => b.index === optionIndex); // 1-based: [___:1] matches option "1." (#1191)
93	
94	      if (blank) {
95	        const selected = selections.get(blank.index);
96	        const isCorrect = submitted && selected?.toLowerCase().trim() === blank.answer.toLowerCase().trim();
97	        const isIncorrect = submitted && selected && !isCorrect;
98	
99	        parts.push(
100	          <select
101	            key={blank.index}
102	            className={`${styles.clozeSelect} ${isCorrect ? styles.correct : ''} ${isIncorrect ? styles.incorrect : ''}`}
103	            data-activity="cloze-blank"
104	            data-blank-index={blank.index}
105	            value={selected || ''}
106	            onChange={(e) => handleSelect(blank.index, e.target.value)}
107	            disabled={submitted}
108	          >
109	            <option value="">---</option>
110	            {blank.options.map((opt, idx) => (
111	              <option key={idx} value={opt}>{opt}</option>
112	            ))}
113	          </select>
114	        );
115	      }
116	
117	      lastIndex = match.index + match[0].length;
118	    }
119	
120	    // Add remaining text
121	    if (lastIndex < text.length) {
122	      parts.push(text.slice(lastIndex));
123	    }
124	
125	    return parts;
126	  };
127	
128	  const allFilled = blanks.every(b => selections.has(b.index) && selections.get(b.index) !== '');
129	
130	  const checkBtnLabel = isUkrainian ? 'Перевірити' : 'Check Answers';
131	  const retryBtnLabel = isUkrainian ? 'Спробувати знову' : 'Try Again';
132	  const successLabel = isUkrainian ? '✓ Всі відповіді правильні!' : '✓ All answers are correct!';
133	  const errorLabel = isUkrainian ? '✗ Деякі відповіді неправильні. Правильні відповіді:' : '✗ Some answers are incorrect. Correct answers:';
134	
135	  return (
136	    <div data-activity="cloze-passage">
137	      <p className={styles.clozePassage}>
138	        {renderText()}
139	      </p>
140	
141	      {!submitted && (
142	        <div className={styles.buttonRow}>
143	          <button
144	            className={styles.submitButton}
145	            onClick={handleSubmit}
146	            disabled={!allFilled}
147	          >
148	            {checkBtnLabel}
149	          </button>
150	        </div>
151	      )}
152	
153	      {submitted && (
154	        <>
155	          <div
156	            className={`${styles.feedback} ${allCorrect ? styles.feedbackCorrect : styles.feedbackIncorrect}`}
157	            data-activity="cloze-feedback"
158	            data-correct={allCorrect ? 'true' : 'false'}
159	          >
160	            {allCorrect ? (
161	              successLabel
162	            ) : (
163	              <>
164	                {errorLabel}{' '}
165	                {blanks.map((b, i) => (
166	                  <span key={i}>
167	                    {i > 0 && ', '}
168	                    <strong>{b.answer}</strong>
169	                  </span>
170	                ))}
171	              </>
172	            )}
173	          </div>
174	          <div className={styles.buttonRow}>
175	            <button className={styles.resetButton} onClick={handleReset}>
176	              {retryBtnLabel}
177	            </button>
178	          </div>
179	        </>
180	      )}
181	    </div>
182	  );
183	}
