214	// Parse passage format with embedded numbered options:
215	// "Text [___:1] more text\n\n1. opt1 | opt2\n   > [!answer] opt1"
216	function parsePassageWithEmbeddedOptions(passage: string): { text: string; blanks: ClozeBlank[] } {
217	  const blanks: ClozeBlank[] = [];
218	
219	  const blocks = passage.split('\n\n');
220	  const firstOptionBlock = blocks.findIndex((block) => {
221	    const separatorIndex = block.indexOf('.');
222	    const numberText = block.slice(0, separatorIndex);
223	    return numberText.length > 0 && [...numberText].every((character) => {
224	      const code = character.charCodeAt(0);
225	      return code >= 48 && code <= 57;
226	    });
227	  });
228	  const text = firstOptionBlock === -1 ? passage : blocks.slice(0, firstOptionBlock).join('\n\n');
229	  const optionLines = blocks.slice(Math.max(firstOptionBlock, 0)).join('\n\n').split('\n');
230	
231	  // Parse numbered options (1. opt1 | opt2\n   > [!answer] correct) without
232	  // repeatedly applying a backtracking expression to untrusted lesson text.
233	  for (let lineIndex = 0; lineIndex < optionLines.length - 1; lineIndex += 1) {
234	    const optionLine = optionLines[lineIndex].trimStart();
235	    const separatorIndex = optionLine.indexOf('.');
236	    const numberText = optionLine.slice(0, separatorIndex);
237	    const hasNumber = numberText.length > 0 && [...numberText].every((character) => {
238	      const code = character.charCodeAt(0);
239	      return code >= 48 && code <= 57;
240	    });
241	
242	    if (!hasNumber) continue;
243	
244	    const answerLine = optionLines[lineIndex + 1].trimStart();
245	    if (!answerLine.startsWith('>')) continue;
246	
247	    const answerText = answerLine.slice(1).trimStart();
248	    if (!answerText.startsWith('[!answer]')) continue;
249	
250	    const answerToken = answerText.slice('[!answer]'.length).trimStart();
251	    const answerEnd = [...answerToken].findIndex((character) => character === ' ' || character === '\t');
252	    const answer = answerEnd === -1 ? answerToken : answerToken.slice(0, answerEnd);
253	    if (!answer) continue;
254	
255	    const options = optionLine.slice(separatorIndex + 1).trim().split('|').map((option) => option.trim());
256	    blanks.push({ index: Number(numberText), options, answer });
257	    lineIndex += 1;
258	  }
259	
260	  return { text, blanks };
261	}
262	
263	export default function Cloze({ passage, blanks = [], instruction, children, isUkrainian, onComplete }: ClozeProps) {
264	  // Parse passage if provided with embedded options
265	  const parsedData = useMemo(() => {
266	    if (passage) {
267	      if (blanks.length > 0) {
268	        // Use provided blanks directly
269	        return { text: passage, blanks };
270	      }
271	      // Parse embedded options from passage
272	      return parsePassageWithEmbeddedOptions(passage);
273	    }
274	    return null;
275	  }, [passage, blanks]);
276	
277	  const headerLabel = isUkrainian ? 'Заповніть текст' : 'Complete the Passage';
278	
279	  return (
280	    <div className={styles.activityContainer} data-activity="cloze">
281	      <div className={styles.activityHeader}>
282	        <span className={styles.activityIcon}>📝</span>
283	        <span>{headerLabel}</span>
284	        <ActivityHelp activityType="cloze" isUkrainian={isUkrainian} />
285	      </div>
286	      {instruction && (
287	        <p className={styles.instruction}><strong>{instruction}</strong></p>
288	      )}
289	      <div className={styles.activityContent}>
290	        {parsedData ? (
291	          <ClozePassage
292	            text={parsedData.text}
293	            blanks={parsedData.blanks}
294	            isUkrainian={isUkrainian}
295	            onComplete={onComplete}
296	          />
297	        ) : children}
298	      </div>
299	    </div>
300	  );
301	}

